    END IF;

    RAISE EXCEPTION 'Cannot modify immutable fiscal evidence: compliance submission %', OLD."id"
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.financial_opening_preserve_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Financial opening evidence is retained'; END IF;
  IF (to_jsonb(NEW) - ARRAY['status','reviewedById','reviewedAt','reviewDigest','reviewKey','reviewCommandHash','conclusion'])
    IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','reviewedById','reviewedAt','reviewDigest','reviewKey','reviewCommandHash','conclusion'])
    OR OLD."status" <> 'STAGED' THEN
    RAISE EXCEPTION 'Financial opening evidence is immutable; stage a new revision';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.financial_opening_preserve_execution()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Opening execution is retained'; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'APPROVED' OR NOT EXISTS (
      SELECT 1 FROM financial_opening_revisions r WHERE r.id = NEW."revisionId" AND r."organizationId" = NEW."organizationId"
      AND r.status = 'REVIEWED' AND r."createdById" <> NEW."approvedById"
      AND r."reviewDigest" = NEW."manifestDigest" AND r."manifestDigest" = NEW."manifestDigest"
    ) THEN RAISE EXCEPTION 'Opening approval requires independent reviewed evidence'; END IF;
  ELSE
    IF OLD.status <> 'APPROVED' OR NEW.status NOT IN ('ACTIVE','CANCELLED') OR
      (to_jsonb(NEW) - ARRAY['status','activeScopeKey','appliedById','appliedAt','applyKey','applyHash','reconciliation','reconciliationHash','cancelledById','cancelledAt','cancellationReason'])
      IS DISTINCT FROM
      (to_jsonb(OLD) - ARRAY['status','activeScopeKey','appliedById','appliedAt','applyKey','applyHash','reconciliation','reconciliationHash','cancelledById','cancelledAt','cancellationReason'])
    THEN RAISE EXCEPTION 'Opening approval and committed receipts are immutable'; END IF;
    IF NEW.status = 'CANCELLED' AND EXISTS (SELECT 1 FROM financial_opening_operations WHERE "executionId" = OLD.id)
    THEN RAISE EXCEPTION 'Opening operations require controlled correction'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_firm_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE engagement firm_engagements%ROWTYPE; previous firm_engagement_assignments%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Assignment history must be retained'; END IF;
  IF TG_OP='UPDATE' THEN
    IF OLD."endedAt" IS NOT NULL OR NEW."endedAt" IS NULL OR
      (to_jsonb(NEW)-ARRAY['endedAt','endedById','endReason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['endedAt','endedById','endReason']) THEN RAISE EXCEPTION 'Assignment can only be ended once'; END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO engagement FROM firm_engagements WHERE id=NEW."engagementId" FOR UPDATE;
  IF NOT FOUND OR engagement.status='ENDED' OR NEW."effectiveFrom" < engagement."effectiveFrom" OR NEW."expiresAt" > engagement."expiresAt" OR
    (engagement.scope='READ_ONLY' AND NEW.scope <> 'READ_ONLY') OR NEW."endedAt" IS NOT NULL THEN RAISE EXCEPTION 'Invalid assignment scope or window'; END IF;
  SELECT * INTO previous FROM firm_engagement_assignments WHERE "engagementId"=NEW."engagementId" AND "accountantUserId"=NEW."accountantUserId" ORDER BY version DESC LIMIT 1;
  IF (FOUND AND (previous."endedAt" IS NULL OR NEW.version <> previous.version+1 OR NEW."effectiveFrom" < LEAST(previous."expiresAt",previous."endedAt"))) OR
    (NOT FOUND AND NEW.version <> 1) THEN RAISE EXCEPTION 'Assignment version or overlap conflict'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_firm_engagement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE receipt firm_engagement_transitions%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Firm engagement must be retained'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status <> 'DRAFT' OR NEW.version <> 0 OR NEW."lastTransitionId" IS NOT NULL THEN RAISE EXCEPTION 'Engagement must start as draft version zero'; END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-ARRAY['status','version','lastTransitionId','updatedAt']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['status','version','lastTransitionId','updatedAt']) THEN RAISE EXCEPTION 'Engagement terms are immutable; end and replace'; END IF;
  IF NEW.status = OLD.status THEN
    IF (NEW.version,NEW."lastTransitionId") IS DISTINCT FROM (OLD.version,OLD."lastTransitionId") THEN RAISE EXCEPTION 'Version requires state change'; END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO receipt FROM firm_engagement_transitions WHERE id=NEW."lastTransitionId" AND "engagementId"=OLD.id;
  IF NOT FOUND OR receipt.version <> OLD.version+1 OR NEW.version <> receipt.version OR
    receipt."fromStatus" <> OLD.status OR receipt."toStatus" <> NEW.status THEN RAISE EXCEPTION 'Matching transition receipt required'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_firm_link_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE mandate accountant_access_grants%ROWTYPE;
BEGIN
  SELECT * INTO mandate FROM accountant_access_grants WHERE id=NEW."grantId" FOR UPDATE;
  IF NOT FOUND OR mandate."organizationId" <> NEW."clientOrganizationId" OR mandate."accountantUserId" <> NEW."accountantUserId" THEN
    RAISE EXCEPTION 'Enrollment must reference the exact named client mandate';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id=NEW."accountantUserId" AND "organizationId"=NEW."firmOrganizationId") THEN
    RAISE EXCEPTION 'Linked accountant must belong to firm';
  END IF;
  -- Physical update also fences repeatable-read writers predating enrollment.
  UPDATE accountant_access_grants SET "activeScopeKey"=CASE WHEN "activeScopeKey" IS NULL THEN NULL
    ELSE 'managed:' || "organizationId" || ':' || "accountantUserId" END,
    "updatedAt"="updatedAt" WHERE id=NEW."grantId";
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_firm_obligation_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior "firm_obligation_revisions"%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Obligation revisions are retained and immutable'; END IF;
  IF NOT EXISTS (SELECT 1 FROM accounting_periods WHERE id=NEW."periodId" AND "organizationId"=NEW."organizationId") THEN RAISE EXCEPTION 'Obligation period tenant mismatch'; END IF;
  IF NEW.version=1 THEN
    IF NEW.decision <> 'PREPARED' THEN RAISE EXCEPTION 'Prepare before review'; END IF;
  ELSE
    SELECT * INTO prior FROM firm_obligation_revisions WHERE "organizationId"=NEW."organizationId" AND "instanceId"=NEW."instanceId" AND version=NEW.version-1;
    IF NOT FOUND OR prior.code<>NEW.code OR prior."periodId"<>NEW."periodId" THEN RAISE EXCEPTION 'Invalid obligation revision chain'; END IF;
    IF NEW.decision IN ('REVIEWED','CHANGES_REQUESTED') AND (prior.decision<>'PREPARED' OR prior."actorId"=NEW."actorId") THEN RAISE EXCEPTION 'Independent review of the latest preparation required'; END IF;
    IF NEW.decision='REVIEWED' AND (NEW."evidenceId" IS NULL OR NEW."evidenceId" IS DISTINCT FROM prior."evidenceId" OR NEW."evidenceHash" IS DISTINCT FROM prior."evidenceHash" OR NEW."sourceHash"<>prior."sourceHash" OR NEW."dueAt" IS DISTINCT FROM prior."dueAt" OR NEW.applicability<>prior.applicability OR NEW."ownerId"<>prior."ownerId") THEN RAISE EXCEPTION 'Review must preserve prepared evidence and terms'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_firm_transition_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current_row firm_engagements%ROWTYPE;
BEGIN
  SELECT * INTO current_row FROM firm_engagements WHERE id=NEW."engagementId" FOR UPDATE;
  IF NOT FOUND OR NEW.version <> current_row.version+1 OR NEW."fromStatus" <> current_row.status THEN RAISE EXCEPTION 'Stale engagement transition'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_journal_period_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE payload JSONB; parent RECORD;
BEGIN
  FOR payload IN SELECT value FROM jsonb_array_elements(CASE TG_OP WHEN 'INSERT' THEN jsonb_build_array(to_jsonb(NEW)) WHEN 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
    IF TG_TABLE_NAME = 'journal_entries' THEN
      PERFORM assert_journal_period_open(payload->>'organizationId', payload->>'periodId', (payload->>'entryDate')::TIMESTAMP);
    ELSE
      SELECT "organizationId", "periodId", "entryDate" INTO parent FROM journal_entries WHERE id = payload->>'journalEntryId';
      IF NOT FOUND THEN
        -- Cascaded deletion follows the already-checked parent DELETE.
        IF TG_OP = 'DELETE' THEN CONTINUE; END IF;
        RAISE EXCEPTION 'Journal line parent is unavailable';
      END IF;
      PERFORM assert_journal_period_open(parent."organizationId", parent."periodId", parent."entryDate");
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.guard_period_control_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE receipt period_control_events%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status::text <> 'OPEN' OR OLD."controlVersion" > 0 THEN RAISE EXCEPTION 'Controlled periods must be retained'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status::text <> 'OPEN' OR NEW."controlVersion" <> 0 OR NEW."lastControlEventId" IS NOT NULL OR
      NEW."closedAt" IS NOT NULL OR NEW."closedById" IS NOT NULL OR NEW."lockedAt" IS NOT NULL THEN
      RAISE EXCEPTION 'New accounting periods must start open without control history';
    END IF;
    RETURN NEW;
  END IF;
  IF (OLD.status::text IN ('CLOSED','LOCKED') OR NEW.status IS DISTINCT FROM OLD.status) AND
    (NEW."organizationId",NEW.id,NEW."fiscalYearId",NEW."startDate",NEW."endDate") IS DISTINCT FROM
    (OLD."organizationId",OLD.id,OLD."fiscalYearId",OLD."startDate",OLD."endDate") THEN
    RAISE EXCEPTION 'Closed period scope cannot be changed';
  END IF;
  IF NEW.status = OLD.status THEN
    IF (NEW."controlVersion",NEW."lastControlEventId",NEW."closedAt",NEW."closedById",NEW."lockedAt") IS DISTINCT FROM
       (OLD."controlVersion",OLD."lastControlEventId",OLD."closedAt",OLD."closedById",OLD."lockedAt") THEN
      RAISE EXCEPTION 'Period control fields require an audited transition';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO receipt FROM period_control_events WHERE id = NEW."lastControlEventId" AND "organizationId" = OLD."organizationId" AND "periodId" = OLD.id;
  IF NOT FOUND OR receipt.version <> OLD."controlVersion" + 1 OR NEW."controlVersion" <> receipt.version OR
    receipt."fromStatus" <> OLD.status::text OR receipt."toStatus" <> NEW.status::text THEN
    RAISE EXCEPTION 'Period transition requires a matching retained receipt and version';
  END IF;
  IF NEW.status::text = 'CLOSED' AND (NEW."closedAt" IS DISTINCT FROM receipt."createdAt" OR NEW."lockedAt" IS DISTINCT FROM receipt."createdAt" OR NEW."closedById" IS DISTINCT FROM receipt."actorId") THEN
    RAISE EXCEPTION 'Close timestamps and actor must match the retained receipt';
  END IF;
  IF NEW.status::text = 'OPEN' AND (NEW."closedAt" IS NOT NULL OR NEW."lockedAt" IS NOT NULL OR NEW."closedById" IS NOT NULL) THEN
    RAISE EXCEPTION 'Reopening must clear active close markers';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hris_bind_employee_document_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE employee_id text; evidence_text text; old_evidence_text text := ''; content_hash text; eligible_count integer;
BEGIN
 IF TG_TABLE_NAME = 'payroll_employees' THEN
   employee_id := NEW.id; evidence_text := COALESCE(NEW.metadata::text,'');
   IF TG_OP='UPDATE' THEN old_evidence_text:=COALESCE(OLD.metadata::text,''); END IF;
 ELSE
   employee_id := NEW."employeeId";
   evidence_text := COALESCE(NEW.metadata::text,'') || COALESCE(NEW."signedDocumentHash",'');
   IF TG_OP='UPDATE' THEN old_evidence_text:=COALESCE(OLD.metadata::text,'') || COALESCE(OLD."signedDocumentHash",''); END IF;
   PERFORM id FROM payroll_employees WHERE id=employee_id AND "organizationId"=NEW."organizationId" FOR UPDATE;
 END IF;
 FOR content_hash IN SELECT DISTINCT sha256 FROM hris_employee_documents
   WHERE "organizationId"=NEW."organizationId" AND "employeeId"=employee_id
   AND position(sha256 in evidence_text)>0 ORDER BY sha256
 LOOP
   PERFORM id FROM hris_employee_documents WHERE "organizationId"=NEW."organizationId" AND "employeeId"=employee_id AND sha256=content_hash ORDER BY id FOR UPDATE;
   SELECT count(*) INTO eligible_count FROM hris_employee_documents WHERE "organizationId"=NEW."organizationId" AND "employeeId"=employee_id AND sha256=content_hash AND status IN ('AVAILABLE','SUPERSEDED');
   IF eligible_count=0 AND position(content_hash in old_evidence_text)=0 THEN RAISE EXCEPTION 'HRIS_DOCUMENT_EVIDENCE_UNAVAILABLE'; END IF;
   UPDATE hris_employee_documents SET "evidenceBoundAt"=COALESCE("evidenceBoundAt",CURRENT_TIMESTAMP),revision=revision+1
     WHERE "organizationId"=NEW."organizationId" AND "employeeId"=employee_id AND sha256=content_hash AND status IN ('AVAILABLE','SUPERSEDED') AND "evidenceBoundAt" IS NULL;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hris_handoff_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'HRIS_HANDOFF_IMMUTABLE'; END IF;
 IF TG_TABLE_NAME='hris_payroll_handoff_packages' THEN
  IF NOT EXISTS(SELECT 1 FROM payroll_periods WHERE id=NEW."payrollPeriodId" AND "organizationId"=NEW."organizationId") THEN RAISE EXCEPTION 'HRIS_HANDOFF_TENANT_MISMATCH'; END IF;
  IF NEW."issuedById"=NEW."recipientUserId" OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW."issuedById" AND "organizationId"=NEW."organizationId") OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW."recipientUserId" AND "organizationId"=NEW."organizationId") THEN RAISE EXCEPTION 'HRIS_HANDOFF_ACTOR_SCOPE_MISMATCH'; END IF;
  IF (NEW.version=1)<>(NEW."replacesPackageId" IS NULL) THEN RAISE EXCEPTION 'HRIS_HANDOFF_LINEAGE_MISMATCH'; END IF;
  IF NEW."replacesPackageId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM hris_payroll_handoff_packages WHERE id=NEW."replacesPackageId" AND "organizationId"=NEW."organizationId" AND "payrollPeriodId"=NEW."payrollPeriodId" AND version=NEW.version-1) THEN RAISE EXCEPTION 'HRIS_HANDOFF_LINEAGE_MISMATCH'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM hris_payroll_handoff_packages WHERE id=NEW."packageId" AND "organizationId"=NEW."organizationId" AND "packageHash"=NEW."packageHash" AND "recipientUserId"=NEW."actorId") THEN RAISE EXCEPTION 'HRIS_HANDOFF_RECEIPT_SCOPE_MISMATCH'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.invalidate_close_on_period_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_row JSONB; new_row JSONB; tenant TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;
  IF TG_OP = 'UPDATE' THEN
    IF old_row = new_row THEN RETURN NEW; END IF;
    IF OLD.status::text = 'OPEN' AND NEW.status::text = 'CLOSED' AND
      (old_row - ARRAY['status','closedAt','lockedAt','closedById','controlVersion','lastControlEventId','updatedAt']) =
      (new_row - ARRAY['status','closedAt','lockedAt','closedById','controlVersion','lastControlEventId','updatedAt']) THEN
      -- a_period_control_transition runs first and requires the matching receipt.
      RETURN NEW;
    END IF;
  END IF;
  FOR tenant IN SELECT DISTINCT value FROM unnest(ARRAY[old_row->>'organizationId',new_row->>'organizationId']) value WHERE value IS NOT NULL ORDER BY value LOOP
    PERFORM advance_close_source_revision(tenant, TG_TABLE_NAME, COALESCE(new_row->>'id',old_row->>'id'), TG_OP);
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.invalidate_close_on_source_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_row JSONB; new_row JSONB; old_org TEXT; new_org TEXT; tenant TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;
  IF TG_OP = 'UPDATE' AND old_row = new_row THEN RETURN NEW; END IF;
  -- Pilot certification is source evidence stored in the audit log. Ordinary
  -- access/close audit records are outputs and must not self-invalidate.
  IF TG_TABLE_NAME = 'audit_logs' AND NOT (
    COALESCE(old_row->>'entityType' = 'PayrollPilotCycleCertification' AND old_row->>'action' = 'PAYROLL_PILOT_CYCLE_CERTIFICATION_EVALUATED', FALSE) OR
    COALESCE(new_row->>'entityType' = 'PayrollPilotCycleCertification' AND new_row->>'action' = 'PAYROLL_PILOT_CYCLE_CERTIFICATION_EVALUATED', FALSE)
  ) THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  -- Close's own evidence/audit events must not invalidate their own publication.
  -- A changed event moving into/out of the close namespace is still a source change.
  IF TG_TABLE_NAME = 'business_events' AND
    (old_row IS NULL OR (old_row->>'eventType' LIKE 'close.%' AND old_row->>'status' NOT IN ('FAILED','REJECTED'))) AND
    (new_row IS NULL OR (new_row->>'eventType' LIKE 'close.%' AND new_row->>'status' NOT IN ('FAILED','REJECTED'))) THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME = 'organizations' THEN
    old_org := old_row->>'id'; new_org := new_row->>'id';
  ELSIF TG_NARGS = 0 THEN
    old_org := old_row->>'organizationId'; new_org := new_row->>'organizationId';
  ELSE
    -- Reviewed child sources inherit tenant from their parent, including both
    -- sides of reassignment. Parent deletions also have their own trigger.
    IF old_row IS NOT NULL THEN EXECUTE format('SELECT "organizationId" FROM %I WHERE id = $1', TG_ARGV[0]) INTO old_org USING old_row->>TG_ARGV[1]; END IF;
    IF new_row IS NOT NULL THEN EXECUTE format('SELECT "organizationId" FROM %I WHERE id = $1', TG_ARGV[0]) INTO new_org USING new_row->>TG_ARGV[1]; END IF;
  END IF;
  FOR tenant IN SELECT DISTINCT value FROM unnest(ARRAY[old_org,new_org]) value WHERE value IS NOT NULL ORDER BY value LOOP
    PERFORM advance_close_source_revision(tenant, TG_TABLE_NAME, COALESCE(new_row->>'id',old_row->>'id'), TG_OP);
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.payment_reconciliation_assert_immutable_evidence(old_row jsonb, new_row jsonb, immutable_label text, allowed_keys text[] DEFAULT ARRAY[]::text[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  normalized_old JSONB := old_row;
  normalized_new JSONB := new_row;
  allowed_key TEXT;
BEGIN
  FOREACH allowed_key IN ARRAY allowed_keys LOOP
    normalized_old := normalized_old - allowed_key;
