  IF normalized_old IS DISTINCT FROM normalized_new THEN
    RAISE EXCEPTION 'Cannot modify immutable payment reconciliation evidence: %', immutable_label
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
END;
$function$

